mapper.select:
SELECT EXISTS (
    SELECT 1 FROM activity_purchase_reservation WHERE user_id = #{userId} AND request_id = #{requestId}
) OR

mapper.update:
UPDATE activity_purchase_reservation
SET status = 'FAILED', fail_reason = #{failReason}
WHERE id = #{id} AND status = 'QUEUED'

UPDATE activity_purchase_reservation
SET status = 'CANCELED', fail_reason = #{failReason}
WHERE order_id = #{orderId} AND status = 'CREATED'

mapper.select:
SELECT COALESCE(SUM(oi.quantity), 0)
FROM order_item oi
JOIN trade_order o ON o.id = oi.order_id
WHERE o.user_id = #{userId}
  AND oi.activity_id = #{activityId}
  AND o.status NOT IN ('CANCELED', 'CLOSED')
